import com.kobil.kssidp.wrapper.models.*
import com.kobil.wrapper.events.AuthenticationMode

fun activateNative(idp: KssIdp, clientId: String, mode: AuthenticationMode,
    credentials: HashMap<String, String>, completion: (KssIdpResultObject) -> Unit) {
