ios.code:
import KSMasterController
import kssidp

func activateNative(idp: KssIdpWrapper, clientId: String,
    mode: KSMAuthenticationMode, credentials: [String: String],
    completion: @escaping KssIdpCompletion) {
    idp.activate(clientId: clientId, authMode: mode,
        credentials: credentials, completion: completion)
}
// The caller retains the configured wrapper and checks its result plus SDK state.
// Credential field names belong to the explicitly selected existing native flow.
